import { gsap } from 'gsap';
import { MeshBasicNodeMaterial } from 'three/webgpu';

export default function createNode(config, ctx) {
  const { Group, Mesh, BoxGeometry, Object3D } = ctx.THREE;

  const container = new Group();
  container.position.fromArray(config.scenePosition || [0, 0, 0]);

  let gltfScene = null;
  let timeline = null;
  const timelines = [];

  const cleanup = () => {
    timelines.forEach(tl => tl.kill());
    if (gltfScene) {
      gltfScene.traverse(child => {
        if (child.geometry) child.geometry.dispose();
        if (child.material) {
          if (Array.isArray(child.material)) {
            child.material.forEach(m => m.dispose());
          } else {
            child.material.dispose();
          }
        }
      });
    }
  };

  container.userData.cleanup = cleanup;
  container.userData.handlers = {};

  ctx.glbLoader.loadGLB(config.meshUrl).then((gltf) => {
    if (!container.parent) return;

    gltfScene = gltf.scene;
    container.add(gltfScene);

    gltfScene.traverse(child => {
      if (child.isMesh) {
        child.castShadow = true;
        child.receiveShadow = true;
      }
    });

    const onHover = () => {
      if (timeline) timeline.kill();
      timeline = gsap.to(container.position, {
        y: container.position.y + 0.15,
        duration: 0.7,
        ease: 'power3.out'
      });
      timelines.push(timeline);
    };

    const onHoverEnd = () => {
      if (timeline) timeline.kill();
      timeline = gsap.to(container.position, {
        y: config.scenePosition?.[1] ?? -0.2,
        duration: 0.9,
        ease: 'power4.out',
        overwrite: 'auto'
      });
      timelines.push(timeline);
    };

    const onPress = () => {
      gsap.to(container.scale, {
        x: 0.97,
        y: 0.97,
        z: 0.97,
        duration: 0.12,
        ease: 'back.out',
        overwrite: 'auto'
      });
    };

    const onRelease = () => {
      gsap.to(container.scale, {
        x: 1,
        y: 1,
        z: 1,
        duration: 0.3,
        ease: 'power2.out',
        overwrite: 'auto'
      });
    };

    const onClick = () => {
      ctx.emit('hub-home.select', { card: 'thumbnail-card' });
    };

    container.userData.handlers = {
      hover: onHover,
      unhover: onHoverEnd,
      press: onPress,
      release: onRelease,
      click: onClick
    };
  }).catch(() => {
    const fallback = new Mesh(
      new BoxGeometry(1, 1, 0.1),
      new MeshBasicNodeMaterial({ color: 0x16161d })
    );
    container.add(fallback);
  });

  return container;
}
